using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class StewardSuccessionTests
{
    static readonly EntityId Home=new("site:kofu"),Owner=new("org:takeda"),Old=new("person:shingen"),Heir=HistoricalHouseholdCatalog.Edition.People.Single().Id;
    static WorldSession Start(bool heir=false)=>new(NewGameWorld.Create(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],heir?Heir.Value:Old.Value,42,historicalCatalog:HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,worldArmyPolicy:NpcArmies.CompactCombatPolicy,economyPolicy:HouseSuccession.Policy));
    static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
    static void At(WorldSession s,long t){while(s.Seconds<t){long old=s.Seconds;s.SetPaused(false);s.AdvanceTo(t,100000);Assert.True(s.Seconds>old);}}
    static void Succeed(WorldSession s){var id=new EntityId("request:steward-head/"+s.Revision);Good(s.ManageHouseSuccession(new(id,HouseSuccessionAction.Nominate,Owner,Heir),s.PlayerControl,s.Revision));Good(s.ManageHouseSuccession(new(new("request:steward-head-confirm/"+s.Revision),HouseSuccessionAction.Confirm,Owner,Original:id),s.PlayerControl,s.Revision));At(s,s.Seconds+1);}
    static EntityId Assign(WorldSession s,int days=30){var id=new EntityId("request:steward-old/"+s.Revision);Good(s.ManageStewardship(new(id,StewardAction.Assign,Home,s.PlayerControl==Old?Heir:Old,Days:days,ReturnAddress:Home),s.PlayerControl,s.Revision));return id;}
    static StewardInput Renew(WorldSession s,EntityId old)=>new(new("request:steward-renew/"+s.Revision),StewardAction.Reauthorize,Home,s.PlayerControl==Heir?Old:Heir,ReturnAddress:Home){PriorGrant=old};
    static EntityId Reauthorize(WorldSession s,EntityId old){var i=Renew(s,old);Good(s.ManageStewardship(i,s.PlayerControl,s.Revision));return i.Id;}
    static HouseholdServiceInput Service(WorldSession s,HouseholdServiceAction a)=>new(new("request:house-personal/"+s.Revision),a,Owner,a==HouseholdServiceAction.Pledge?Heir:s.HouseholdServiceView()!.Principal!.Value,a==HouseholdServiceAction.Release?s.HouseholdServiceView()!.Source:null);
    static void ReleaseReciprocal(WorldSession s){foreach(var b in s.HouseholdServiceView()!.Releases.Where(b=>b.Subject!=s.PlayerControl&&b.CanRelease).ToArray())Good(s.ManageHouseholdService(new(new("request:release-old-retainer/"+s.Revision),HouseholdServiceAction.Release,Owner,b.Other,b.Source),s.PlayerControl,s.Revision));}
    [Fact]public void PersonalReleaseKeepsHouseOfficeLandMoneyAndOldHistory(){var s=Start(true);Succeed(s);var a=s.DiagnosticSnapshot();var old=s.HouseholdServiceView()!.Source;Good(s.ManageHouseholdService(Service(s,HouseholdServiceAction.Release),Heir,s.Revision));var w=s.DiagnosticSnapshot();Assert.Equal(ContractJson.Write(a.Memberships),ContractJson.Write(w.Memberships));Assert.Equal(ContractJson.Write(a.Offices),ContractJson.Write(w.Offices));Assert.Equal(ContractJson.Write(a.LandRights),ContractJson.Write(w.LandRights));Assert.Equal(ContractJson.Write(a.ResourceLots),ContractJson.Write(w.ResourceLots));Assert.Contains(w.ServiceBonds,b=>b.Id==old&&b.Target==Old&&b.Until==s.Seconds);Assert.False(NewGameService.BoundAt(w,Old,s.Seconds,s.Revision));Assert.Equal(Owner,NewGameService.View(w).House);Assert.Null(NewGameService.View(w).Principal);new WorldSession(ContractJson.Copy(w));}
    [Fact]public void RetiredHeadCanSeparatelyPledgeNewHeadWithoutChangingMembership(){var s=Start();Succeed(s);var a=s.DiagnosticSnapshot();Assert.False(s.HouseholdServiceView()!.CanPledge);ReleaseReciprocal(s);Assert.True(s.HouseholdServiceView()!.CanPledge);Good(s.ManageHouseholdService(Service(s,HouseholdServiceAction.Pledge),Old,s.Revision));var w=s.DiagnosticSnapshot();Assert.Equal(ContractJson.Write(a.Memberships),ContractJson.Write(w.Memberships));Assert.True(NewGameService.BoundAt(w,Heir,s.Seconds,s.Revision));Assert.Equal(Heir,NewGameService.View(w).Principal);Assert.Null(FactionStances.ResolveAuthority(w,Old,Owner,s.Seconds,s.Revision));new WorldSession(ContractJson.Copy(w));}
    [Fact]public void HeadCannotPledgeItselfAndZeroLengthPersonalBondsAreRejected(){var s=Start();Succeed(s);ReleaseReciprocal(s);Good(s.ManageHouseholdService(Service(s,HouseholdServiceAction.Pledge),Old,s.Revision));Assert.Equal(ResultCode.NotAvailable,s.ManageHouseholdService(Service(s,HouseholdServiceAction.Release),Old,s.Revision).Code);At(s,s.Seconds+1);Good(s.ManageHouseholdService(Service(s,HouseholdServiceAction.Release),Old,s.Revision));Assert.Null(s.HouseholdServiceView()!.Principal);var h=Start(true);Succeed(h);Good(h.ManageHouseholdService(Service(h,HouseholdServiceAction.Release),Heir,h.Revision));Assert.False(h.HouseholdServiceView()!.CanPledge);}
    [Theory][InlineData(false)][InlineData(true)]public void ExplicitAdministrativeReauthorizationKeepsOriginalsAndOriginalExpiry(bool headPlayer){var s=Start(headPlayer);var old=Assign(s,1);Succeed(s);var a=s.DiagnosticSnapshot();var id=Reauthorize(s,old);var w=s.DiagnosticSnapshot();Assert.Equal(2,w.Stewardship!.Grants.Length);Assert.Contains(a.Stewardship!.Grants.Single(),w.Stewardship.Grants);var g=w.Stewardship.Grants.Single(g=>g.Id==id);Assert.Equal(Heir,g.Principal);Assert.Equal(Old,g.Agent);Assert.Equal(86400,g.Until);Assert.Equal(ContractJson.Write(a.Memberships),ContractJson.Write(w.Memberships));Assert.Equal(ContractJson.Write(a.ServiceBonds),ContractJson.Write(w.ServiceBonds));Assert.Equal(ContractJson.Write(a.ResourceLots),ContractJson.Write(w.ResourceLots));Assert.Equal(ContractJson.Write(a.Units),ContractJson.Write(w.Units));if(!headPlayer){Assert.True(s.StewardshipView()!.Grants.Single(c=>c.Id==id).CanOperate);Good(s.ManageStewardship(new(new("request:reauthorized-water"),StewardAction.Operate,Home,Grant:id,Operation:EconomyAction.ImproveWater,Amount:200),Old,s.Revision));}new WorldSession(ContractJson.Copy(s.DiagnosticSnapshot()));}
    [Fact]public void NoAdministrativeReauthorizationCanBeInferredFromOfficeChange(){var s=Start(true);var old=Assign(s);Succeed(s);Assert.False(s.StewardshipView()!.Grants.Single().CanOperate);Assert.Single(s.DiagnosticSnapshot().Stewardship!.Grants);Assert.Equal(ResultCode.NotAvailable,s.ManageStewardship(new(new("request:old-admin-no-authority"),StewardAction.Operate,Home,Grant:old,Operation:EconomyAction.RelieveVillage,Amount:1),Heir,s.Revision).Code);}
    [Fact]public void LateOldCancellationCannotStopTheDistinctNewGrant(){var s=Start();var old=Assign(s);Succeed(s);Good(s.ManageStewardship(new(new("request:old-revoke-in-flight"),StewardAction.Revoke,Home,Grant:old),Old,s.Revision));var fresh=Reauthorize(s,old);At(s,s.Seconds+2);Assert.Contains(s.DiagnosticSnapshot().Stewardship!.Receipts,r=>s.DiagnosticSnapshot().Stewardship!.Papers.Any(p=>p.Id==r.Message&&p.Grant==old));Assert.True(s.StewardshipView()!.Grants.Single(g=>g.Id==fresh).CanOperate);Assert.False(s.StewardshipView()!.Grants.Single(g=>g.Id==old).CanOperate);new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void SameOriginalCannotRenewTwiceOrRewritePayload(){var s=Start();var old=Assign(s);Succeed(s);var i=Renew(s,old);Good(s.ManageStewardship(i,Old,s.Revision));Assert.Equal(ResultCode.AlreadyAccepted,s.ManageStewardship(i,Old,s.Revision).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.ManageStewardship(i with{Days=1},Old,s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.ManageStewardship(Renew(s,old),Old,s.Revision).Code);Assert.Equal(2,s.DiagnosticSnapshot().Stewardship!.Grants.Length);}
    [Fact]public void ExpiredOriginalCannotBeReauthorized(){var s=Start();var old=Assign(s,1);Succeed(s);At(s,86400);Assert.Equal(ResultCode.NotAvailable,s.ManageStewardship(Renew(s,old),Old,s.Revision).Code);}
    [Fact]public void PersonalAndAdministrativeAgreementsAreIndependent(){var s=Start();var old=Assign(s);Succeed(s);var fresh=Reauthorize(s,old);var original=ContractJson.Write(s.DiagnosticSnapshot().Stewardship);ReleaseReciprocal(s);Good(s.ManageHouseholdService(Service(s,HouseholdServiceAction.Pledge),Old,s.Revision));Assert.Equal(original,ContractJson.Write(s.DiagnosticSnapshot().Stewardship));Assert.True(s.StewardshipView()!.Grants.Single(g=>g.Id==fresh).CanOperate);At(s,s.Seconds+1);Good(s.ManageHouseholdService(Service(s,HouseholdServiceAction.Release),Old,s.Revision));Assert.True(s.StewardshipView()!.Grants.Single(g=>g.Id==fresh).CanOperate);new WorldSession(s.DiagnosticSnapshot());}

    static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Good(s.Open(s.PlayerControl,m.Id,s.Revision));}
    static void Move(WorldSession s,string node){Good(s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:steward-trip/"+s.Revision,node),s.Revision));At(s,s.Seconds+2);At(s,s.DiagnosticSnapshot().Branches!.Journeys.Last(j=>j.Actor==s.PlayerControl).Legs[^1].EndAt+1);}
    [Fact]public void NewAdministrativeAgentCannotCancelOrOperateOldPrincipalOriginal(){var s=Start();var old=Assign(s);Succeed(s);var fresh=Reauthorize(s,old);Assert.False(s.StewardshipView()!.Grants.Single(g=>g.Id==fresh).CanRevoke);Assert.Equal(ResultCode.NotAvailable,s.ManageStewardship(new(new("request:unauthorized-new-cancel"),StewardAction.Revoke,Home,Grant:fresh),Old,s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.ManageStewardship(new(new("request:wrong-old-operation"),StewardAction.Operate,Home,Grant:old,Operation:EconomyAction.RelieveVillage,Amount:1),Old,s.Revision).Code);}
    [Fact]public void NewHeadCanCancelOnlyTheNewOriginalByPhysicalDelivery(){var s=Start(true);var old=Assign(s);Succeed(s);var fresh=Reauthorize(s,old);Good(s.ManageStewardship(new(new("request:new-head-cancel"),StewardAction.Revoke,Home,Grant:fresh),Heir,s.Revision));var a=s.DiagnosticSnapshot();Assert.DoesNotContain(a.Stewardship!.Receipts,r=>a.Stewardship.Papers.Any(p=>p.Id==r.Message&&p.Grant==fresh));At(s,s.Seconds+2);Assert.Contains(s.DiagnosticSnapshot().Stewardship!.Receipts,r=>s.DiagnosticSnapshot().Stewardship!.Papers.Any(p=>p.Id==r.Message&&p.Grant==fresh));Assert.DoesNotContain(s.DiagnosticSnapshot().Stewardship!.Receipts,r=>s.DiagnosticSnapshot().Stewardship!.Papers.Any(p=>p.Id==r.Message&&p.Grant==old));new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void OriginalCancellationAlreadyReceivedPreventsReauthorization(){var s=Start();var old=Assign(s);Succeed(s);Good(s.ManageStewardship(new(new("request:cancel-before-reconfirm"),StewardAction.Revoke,Home,Grant:old),Old,s.Revision));At(s,s.Seconds+2);Assert.Equal(ResultCode.NotAvailable,s.ManageStewardship(Renew(s,old),Old,s.Revision).Code);}
    [Fact]public void NoHeadChangeMeansNoReauthorization(){var s=Start();var old=Assign(s);Assert.Empty(s.StewardReauthorizationView());Assert.Equal(ResultCode.NotAvailable,s.ManageStewardship(Renew(s,old),Old,s.Revision).Code);}
    [Fact]public void RemoteFormerHeadCannotAuthorizeAReplacement(){var s=Start();var old=Assign(s);Succeed(s);Move(s,"castle");Assert.Empty(s.StewardReauthorizationView());Assert.Equal(ResultCode.NotAvailable,s.ManageStewardship(Renew(s,old),Old,s.Revision).Code);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)]public void InvalidReauthorizationScopeDoesNotChangeAnOriginal(int kind){var s=Start();var old=Assign(s);Succeed(s);var i=Renew(s,old);i=kind switch{0=>i with{PriorGrant=new("request:missing-old-grant")},1=>i with{Site=new("site:castle")},2=>i with{Days=31},3=>i with{ReturnAddress=null},_=>i with{Action=StewardAction.Report}};var a=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.ManageStewardship(i,Old,s.Revision).Code);Assert.Equal(a,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void StaleAdministrativeConfirmationAndWrongActorAreRefused(){var s=Start();var old=Assign(s);Succeed(s);var i=Renew(s,old);Assert.Equal(ResultCode.StateChanged,s.ManageStewardship(i,Old,s.Revision-1).Code);Assert.Equal(ResultCode.NotAvailable,s.ManageStewardship(i,Heir,s.Revision).Code);Assert.Single(s.DiagnosticSnapshot().Stewardship!.Grants);}
    [Fact]public void SecondGrantRetainsTheShorterExplicitTerm(){var s=Start();var old=Assign(s,30);Succeed(s);Good(s.ManageStewardship(Renew(s,old) with{Days=1},Old,s.Revision));var g=s.DiagnosticSnapshot().Stewardship!.Grants.Last();Assert.Equal(s.Seconds+86400,g.Until);Assert.True(g.Until<s.DiagnosticSnapshot().Stewardship!.Grants.First().Until);}
    [Fact]public void SameMonthWaterBudgetDoesNotResetWhenTheActualAgentChanges(){var s=Start();var old=Assign(s);Good(s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:old-head-away","castle"),s.Revision));At(s,86400);Assert.Contains(s.DiagnosticSnapshot().Communities!.Orders,o=>o.Actor==Heir&&o.Input.Site==Home&&o.Input.Action==EconomyAction.ImproveWater&&o.Input.Amount==200);At(s,s.DiagnosticSnapshot().Branches!.Journeys.Single(j=>j.Actor==Old).Legs[^1].EndAt+1);Move(s,"kofu");Succeed(s);var fresh=Reauthorize(s,old);var a=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.ManageStewardship(new(new("request:no-reset-water"),StewardAction.Operate,Home,Grant:fresh,Operation:EconomyAction.ImproveWater,Amount:200),Old,s.Revision).Code);Assert.Equal(a,ContractJson.Write(s.DiagnosticSnapshot()));new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void ActualOutstandingCarrierAdvanceConsumesSuccessorAgentsSharedProcurementCap(){var s=Start();Good(s.ManageHouseTreasury(new(new("request:shared-house-budget"),TreasuryAction.SetBudget,Home,Amount:1000),Old,s.Revision));var old=Assign(s);var freight=new EntityId("request:old-delegated-trust");Good(s.ManageHouseFreight(new(freight,HouseFreightAction.Dispatch,Home:Home,Source:new("site:castle"),Commodity:"wood",Quantity:10,Advance:200){Carrier=Heir},Old,s.Revision));var original=ContractJson.Write(s.DiagnosticSnapshot().HouseFreight);Succeed(s);Reauthorize(s,old);Assert.Equal(0,s.HouseTreasuryView()!.Remaining);Assert.Equal(ResultCode.NotAvailable,s.ManageHouseTreasury(new(new("request:no-new-agent-reset"),TreasuryAction.Buy,Home,"wood",1),Old,s.Revision).Code);Assert.Equal(original,ContractJson.Write(s.DiagnosticSnapshot().HouseFreight));Assert.Equal(Old,HouseLogistics.FreightJobs(s.DiagnosticSnapshot(),s.Seconds,s.Revision+1).Single().Terms.Principal);new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void ReauthorizedNpcActsLocallyWhileNewHeadIsAwayAndDoesNotAutoControlThePlayer(){var s=Start(true);var old=Assign(s);Succeed(s);var fresh=Reauthorize(s,old);Good(s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:new-head-away","castle"),s.Revision));At(s,86400);var w=s.DiagnosticSnapshot();Assert.Contains(w.CommunityAdministration!.Decisions,d=>d.Site==Home&&d.Actor==Old&&d.Action==EconomyAction.ImproveWater);Assert.DoesNotContain(w.CommunityAdministration.Decisions,d=>d.Actor==Heir);Assert.Contains(w.Stewardship!.Papers,p=>p.Grant==fresh&&p.Kind==CommunityStewardship.ReportKind&&p.Sender==Old&&p.Recipient==Heir);Assert.Empty(s.StewardshipView()!.Reports);new WorldSession(ContractJson.Copy(w));}
    [Fact]public void OldObservedReportKeepsItsOriginalRecipientAndObservation(){var s=Start(true);var old=Assign(s);Good(s.ManageStewardship(new(new("request:old-observed-report"),StewardAction.Report,Home,Grant:old),Heir,s.Revision));var report=s.DiagnosticSnapshot().Stewardship!.Papers.Single(p=>p.Kind==CommunityStewardship.ReportKind);Succeed(s);Reauthorize(s,old);var w=s.DiagnosticSnapshot();Assert.Contains(report,w.Stewardship!.Papers);Assert.Equal(Old,report.Recipient);Assert.Equal(0,report.Observation!.ObservedAt);Assert.All(w.Messaging.Messages.Where(m=>m.Id==report.Id),m=>Assert.Equal(Old.Value,m.RecipientId));new WorldSession(ContractJson.Copy(w));}
    [Fact]public void IndividualReleaseRequiresTheActualOldBondAndDoesNotAutomaticallyPledge(){var s=Start(true);Succeed(s);var bad=Service(s,HouseholdServiceAction.Release) with{Source=new("service:missing")};Assert.Equal(ResultCode.NotAvailable,s.ManageHouseholdService(bad,Heir,s.Revision).Code);Good(s.ManageHouseholdService(Service(s,HouseholdServiceAction.Release),Heir,s.Revision));Assert.Null(NewGameService.View(s.DiagnosticSnapshot()).Principal);Assert.DoesNotContain(s.DiagnosticSnapshot().ServiceBonds,b=>b.Subject==Heir&&b.From==s.Seconds&&b.Until==long.MaxValue);}
    [Fact]public void ReciprocalOldServiceMustBeReleasedBeforeRetiredHeadCanPledgeSuccessor(){var s=Start();Succeed(s);var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.ManageHouseholdService(Service(s,HouseholdServiceAction.Pledge),Old,s.Revision).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));ReleaseReciprocal(s);Assert.True(s.HouseholdServiceView()!.CanPledge);Good(s.ManageHouseholdService(Service(s,HouseholdServiceAction.Pledge),Old,s.Revision));new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void PendingTrustCargoBlocksReleasingItsCarriersOldPersonalService(){var s=Start();var freight=new EntityId("request:retainer-trust-before-service-release");Good(s.ManageHouseFreight(new(freight,HouseFreightAction.Dispatch,Home:Home,Source:new("site:castle"),Commodity:"wood",Quantity:10,Advance:200){Carrier=Heir},Old,s.Revision));Succeed(s);var source=s.HouseholdServiceView()!.Releases.Single(b=>b.Subject==Heir);Assert.False(source.CanRelease);Assert.Equal(ResultCode.NotAvailable,s.ManageHouseholdService(new(new("request:no-free-before-trust-return"),HouseholdServiceAction.Release,Owner,Heir,source.Source),Old,s.Revision).Code);Assert.Single(s.DiagnosticSnapshot().HouseFreight!.Entries);}
    [Fact]public void NewMilitaryCustodyBlocksPrematurePersonalServiceRelease(){var s=Start(true);Succeed(s);Good(s.DecideNewMilitary(new(new("request:personal-service-military"),NewMilitaryAction.Request){AuthorityPolicy=NewGameMilitary.AuthorityContract,LedgerPolicy=NewGameMilitary.LedgerIdentityContract},Heir,s.Revision));At(s,s.Seconds+2);Open(s);Good(s.DecideNewMilitary(new(new("request:personal-service-military-answer"),NewMilitaryAction.Accept),Heir,s.Revision));At(s,s.Seconds+2);Open(s);Good(s.DecideNewMilitary(new(new("request:personal-service-military-pickup"),NewMilitaryAction.Pickup),Heir,s.Revision));Assert.False(s.HouseholdServiceView()!.CanRelease);Assert.Equal(ResultCode.NotAvailable,s.ManageHouseholdService(Service(s,HouseholdServiceAction.Release),Heir,s.Revision).Code);Assert.True(NewGameMilitary.View(s.DiagnosticSnapshot()).Custody);}
    [Fact]public void PersonalRepeatConflictWrongActorAndStaleViewCannotDuplicateRelations(){var s=Start(true);Succeed(s);var i=Service(s,HouseholdServiceAction.Release);Assert.Equal(ResultCode.NotAvailable,s.ManageHouseholdService(i,Old,s.Revision).Code);Assert.Equal(ResultCode.StateChanged,s.ManageHouseholdService(i,Heir,s.Revision-1).Code);Good(s.ManageHouseholdService(i,Heir,s.Revision));Assert.Equal(ResultCode.AlreadyAccepted,s.ManageHouseholdService(i,Heir,s.Revision).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.ManageHouseholdService(i with{Other=new("person:nobunaga")},Heir,s.Revision).Code);Assert.Single(s.DiagnosticSnapshot().HouseService!.Entries);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)]public void ForgedPersonalRelationshipOrLedgerFailsLoading(int kind){var s=Start(true);Succeed(s);Good(s.ManageHouseholdService(Service(s,HouseholdServiceAction.Release),Heir,s.Revision));var w=s.DiagnosticSnapshot();if(kind==0)w.HouseService=w.HouseService! with{Policy="forged"};if(kind==1)w.HouseService!.Entries[0]=w.HouseService.Entries[0] with{Subject=Old};if(kind==2)w.HouseService!.Entries[0]=w.HouseService.Entries[0] with{Input=w.HouseService.Entries[0].Input with{Source=new("service:other")}};if(kind==3)w.ServiceBonds=w.ServiceBonds.Select(b=>b.Subject==Heir?b with{Until=long.MaxValue}:b).ToArray();Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)]public void ForgedAdministrativeSourceAgentOrExpiryFailsLoading(int kind){var s=Start();var old=Assign(s);Succeed(s);Reauthorize(s,old);var w=s.DiagnosticSnapshot();if(kind==0)w.Stewardship!.Entries[^1]=w.Stewardship.Entries[^1] with{Input=w.Stewardship.Entries[^1].Input with{PriorGrant=null}};if(kind==1)w.Stewardship!.Grants[^1]=w.Stewardship.Grants[^1] with{Agent=Heir};if(kind==2)w.Stewardship!.Grants[^1]=w.Stewardship.Grants[^1] with{Until=long.MaxValue};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)][InlineData(5)][InlineData(6)][InlineData(7)]public void AdministrativeGenerationRecoveryAndFutureRemainExact(int phase){var s=Start(phase>=6);var old=Assign(s);if(phase>0)Succeed(s);EntityId? fresh=null;if(phase==3)Good(s.ManageStewardship(new(new("request:saved-old-cancellation"),StewardAction.Revoke,Home,Grant:old),s.PlayerControl,s.Revision));if(phase>=2)fresh=Reauthorize(s,old);if(phase==4)Good(s.ManageStewardship(new(new("request:saved-current-report"),StewardAction.Report,Home,Grant:fresh),s.PlayerControl,s.Revision));if(phase==5){Good(s.ManageStewardship(new(new("request:saved-superseded-cancel"),StewardAction.Revoke,Home,Grant:old),s.PlayerControl,s.Revision));At(s,s.Seconds+2);}if(phase==6){Good(s.ManageStewardship(new(new("request:saved-new-cancel"),StewardAction.Revoke,Home,Grant:fresh),s.PlayerControl,s.Revision));At(s,s.Seconds+2);}SaveAndFuture(s,"steward-succession-"+phase);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)]public void PersonalGenerationRecoveryAndFutureRemainExact(int phase){var s=Start(phase==0);var old=Assign(s);Succeed(s);Reauthorize(s,old);if(phase==0)Good(s.ManageHouseholdService(Service(s,HouseholdServiceAction.Release),s.PlayerControl,s.Revision));else{ReleaseReciprocal(s);if(phase>=2)Good(s.ManageHouseholdService(Service(s,HouseholdServiceAction.Pledge),s.PlayerControl,s.Revision));if(phase==3){At(s,s.Seconds+1);Good(s.ManageHouseholdService(Service(s,HouseholdServiceAction.Release),s.PlayerControl,s.Revision));}}SaveAndFuture(s,"household-service-"+phase);}
    static void SaveAndFuture(WorldSession s,string name){s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"steward-succession-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(s,"handover",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("handover"),host.Current,host.Current.Revision));var c=host.Current;Assert.Equal(ContractJson.Write(w),ContractJson.Write(c.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(s.HouseholdServiceView()),ContractJson.Write(c.HouseholdServiceView()));Assert.Equal(ContractJson.Write(s.StewardshipView()),ContractJson.Write(c.StewardshipView()));var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(!string.IsNullOrEmpty(dir)){File.WriteAllBytes(Path.Combine(dir,name+".before.json"),ContractJson.Write(w));File.WriteAllBytes(Path.Combine(dir,name+".restored.json"),ContractJson.Write(c.DiagnosticSnapshot()));}foreach(var x in new[]{s,c})At(x,x.Seconds+10);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(c.DiagnosticSnapshot()));}

    [Theory][InlineData(false)][InlineData(true)]public void ReplacementAgentNeedsItsOwnConsentAndKeepsOriginalPrivateLord(bool willing){var id=new EntityId("created:steward-replacement");var basis=NewGameWorld.Scenario(HistoricalStartCatalog.Current);var officers=NewGameWorld.Normalize([NewGameWorldTests.Officer(id.Value,StartTemplate.Retainer,"site:kofu",Old.Value)]);var request=new WorldSetupRequest(officers,[]);var preview=NewGameSetup.Preview(basis,request);Assert.True(preview.IsEligible());var scenario=NewGameSetup.Confirm(basis,request,preview);var w=NewGameWorld.Create(scenario,officers,Old.Value,42,historicalCatalog:HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,worldArmyPolicy:NpcArmies.CompactCombatPolicy,economyPolicy:HouseSuccession.Policy);if(!willing)w.Characters=w.Characters.Select(c=>c.Id==id?c with{WillObey=false}:c).ToArray();var s=new WorldSession(w);var old=Assign(s);Succeed(s);var before=ContractJson.Write(s.DiagnosticSnapshot().ServiceBonds);var i=Renew(s,old) with{Other=id};var result=s.ManageStewardship(i,Old,s.Revision);Assert.Equal(willing?ResultCode.Accepted:ResultCode.NotAvailable,result.Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot().ServiceBonds));if(willing){Assert.Equal(id,s.DiagnosticSnapshot().Stewardship!.Grants.Last().Agent);Assert.Contains(s.DiagnosticSnapshot().ServiceBonds,b=>b.Subject==id&&b.Target==Old&&b.Until==long.MaxValue);Assert.DoesNotContain(s.DiagnosticSnapshot().ServiceBonds,b=>b.Subject==id&&b.Target==Heir);}else Assert.DoesNotContain(s.StewardReauthorizationView().SelectMany(c=>c.Agents),a=>a==id);new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void LegacyStewardPolicyRejectsSuccessionActionsAndRetainsExactBytes(){var s=new WorldSession(NewGameWorld.Create(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],Old.Value,42,historicalCatalog:HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,economyPolicy:CommunityStewardship.Policy));var old=Assign(s);var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.DoesNotContain("HouseService",System.Text.Encoding.UTF8.GetString(before));Assert.Null(s.HouseholdServiceView());Assert.Empty(s.StewardReauthorizationView());Assert.Equal(ResultCode.NotAvailable,s.ManageHouseholdService(new(new("request:legacy-house-personal"),HouseholdServiceAction.Pledge,Owner,Heir),Old,s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.ManageStewardship(Renew(s,old),Old,s.Revision).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));Assert.Equal(before,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(before)).DiagnosticSnapshot()));}
    [Fact]public void ExistingHouseholdServiceIdCannotBeReusedByAnAdministrativeOriginal(){var s=Start(true);var old=Assign(s);Succeed(s);var i=Service(s,HouseholdServiceAction.Release);Good(s.ManageHouseholdService(i,Heir,s.Revision));Assert.Equal(ResultCode.IdPayloadConflict,s.ManageStewardship(Renew(s,old) with{Id=i.Id},Heir,s.Revision).Code);Assert.Single(s.DiagnosticSnapshot().Stewardship!.Grants);}
    [Theory][InlineData("Subject")][InlineData("Site")][InlineData("Revision")]public void OptionalWorldExtensionDoesNotRelaxRequiredPersonalEntryFields(string property){var s=Start(true);Succeed(s);Good(s.ManageHouseholdService(Service(s,HouseholdServiceAction.Release),Heir,s.Revision));var node=System.Text.Json.Nodes.JsonNode.Parse(ContractJson.Write(s.DiagnosticSnapshot()))!;node["HouseService"]!["Entries"]![0]!.AsObject().Remove(property);Assert.Throws<InvalidDataException>(()=>ContractJson.Read<ContractWorld>(System.Text.Encoding.UTF8.GetBytes(node.ToJsonString())));}
    [Fact]public void PersonalReleasePreservesAnExistingSalaryDebt(){var s=Start(true);var salary=new EntityId("request:salary-before-personal-end");Good(s.ManageSalary(new(salary,SalaryAction.Propose,Old,Home,Amount:20),Heir,s.Revision));Good(s.ManageSalary(new(new("request:salary-before-personal-confirm"),SalaryAction.Confirm,Old,Home,salary),Heir,s.Revision));At(s,s.DiagnosticSnapshot().Salary!.Terms.Single().DueAt[0]);Succeed(s);var debt=ContractJson.Write(s.DiagnosticSnapshot().Salary);Good(s.ManageHouseholdService(Service(s,HouseholdServiceAction.Release),Heir,s.Revision));Assert.Equal(debt,ContractJson.Write(s.DiagnosticSnapshot().Salary));Assert.Equal(20,s.SalaryView()!.Contracts.Single().Owed);Assert.Equal(Old,s.DiagnosticSnapshot().Salary!.Terms.Single().Employer);new WorldSession(s.DiagnosticSnapshot());}

    [Fact]public void SameSecondPledgeDoesNotBecomeAnEarlierMilitaryAuthorityProof(){var s=Start();Succeed(s);ReleaseReciprocal(s);long before=s.Revision;Good(s.ManageHouseholdService(Service(s,HouseholdServiceAction.Pledge),Old,s.Revision));long pledged=s.Revision;var w=s.DiagnosticSnapshot();var prior=ContractJson.Copy(w);prior.CommitSequence=before;Assert.Null(NewGameMilitaryAuthority.Resolve(prior,Heir,Old,Owner,Home));var source=NewGameMilitaryAuthority.Resolve(w,Heir,Old,Owner,Home);Assert.NotNull(source);At(s,s.Seconds+1);Good(s.ManageHouseholdService(Service(s,HouseholdServiceAction.Release),Old,s.Revision));var later=s.DiagnosticSnapshot();Assert.Null(NewGameMilitaryAuthority.Resolve(later,Heir,Old,Owner,Home));later.ElapsedSeconds=w.ElapsedSeconds;later.CommitSequence=pledged;Assert.Equal(source,NewGameMilitaryAuthority.Resolve(later,Heir,Old,Owner,Home));}
    [Fact]public void EarlierSameSecondGrantCannotBorrowALaterPersonalPledge(){var s=Start();Succeed(s);ReleaseReciprocal(s);long before=s.Revision;Good(s.ManageHouseholdService(Service(s,HouseholdServiceAction.Pledge),Old,s.Revision));Assign(s);var w=s.DiagnosticSnapshot();w.Stewardship!.Entries[0]=w.Stewardship.Entries[0] with{Revision=before};w.Stewardship.Grants[0]=w.Stewardship.Grants[0] with{Revision=before};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void HistoricalHeadCandidateDoesNotSeeALaterSameSecondPersonalPledge(){var s=Start();Succeed(s);ReleaseReciprocal(s);long before=s.Revision;Good(s.ManageHouseholdService(Service(s,HouseholdServiceAction.Pledge),Old,s.Revision));var prior=s.DiagnosticSnapshot();prior.CommitSequence=before;Assert.DoesNotContain(HouseSuccession.ViewForProjection(prior)!.Candidates,c=>c.Person==Old);Assert.Contains(s.HouseSuccessionView()!.Candidates,c=>c.Person==Old);}
